module WhbThermo.Tests.MixtureGoldenTests

open System
open System.Globalization
open System.IO
open Xunit
open Ganfoss.ROP
open WhbThermo.Domain
open WhbThermo.Data
open WhbThermo.Properties

/// Golden-file campaign against Cantera, generated by tools/generate_golden.py.
///
/// The design deliberately separates two failure modes that an end-to-end
/// mixture test would conflate:
///   * a wrong MIXING RULE   -> tested here, on Cantera's own pure-species values
///   * wrong SPECIES DATA    -> tested in PureComponentGoldenTests against CoolProp
module private Reference =

    let private path name = Path.Combine(AppContext.BaseDirectory, "reference", name)

    let private readCsv name =
        let file = path name
        if not (File.Exists file) then [||]
        else
            let lines = File.ReadAllLines file
            let header = lines.[0].Split(',')
            lines
            |> Array.skip 1
            |> Array.map (fun line ->
                let cells = line.Split(',')
                Array.zip header cells |> Map.ofArray)

    let number (row: Map<string, string>) key =
        Double.Parse(row.[key], CultureInfo.InvariantCulture)

    let components = readCsv "cantera-mixture-components.csv"
    let results = readCsv "cantera-mixture-results.csv"

    let available = components.Length > 0 && results.Length > 0

    /// Rows for one (case, temperature), in file order.
    let componentsFor (case: string) (t: string) =
        components |> Array.filter (fun r -> r.["case"] = case && r.["T_K"] = t)

open Reference

/// Wilke is what Cantera implements for viscosity, so this is an exact
/// comparison of two implementations of one formula, not a model comparison.
/// A tolerance of 0.1 % is appropriate; anything larger is a real defect.
[<Fact>]
let ``Wilke viscosity mixing reproduces Cantera exactly`` () =
    Assert.True(available, "run tools/generate_golden.py first")

    let failures = ResizeArray<string>()
    for row in results do
        let case = row.["case"]
        let t = row.["T_K"]
        let parts = componentsFor case t
        Assert.NotEmpty(parts)

        let total = parts |> Array.sumBy (fun r -> number r "moleFraction")
        let input =
            parts
            |> Array.map (fun r ->
                number r "moleFraction" / total,
                number r "molarMass_g_mol",
                number r "mu_Pas")

        let ours = Mixing.combine input
        let reference = number row "mu_Pas"
        let deviation = abs (ours - reference) / reference
        if deviation > 1e-3 then
            failures.Add $"{case} @ {t} K: {deviation:P3} (ours {ours:e4}, Cantera {reference:e4})"

    Assert.True(failures.Count = 0, String.Join("\n", failures))

/// Cantera implements Mathur-Tondon-Saxena for conductivity, a DIFFERENT model
/// from Wassiljewa, so it cannot be a direct oracle. What can be asserted
/// rigorously is that our result stays inside the bounds every admissible
/// mixture conductivity must satisfy.
[<Fact>]
let ``Wassiljewa conductivity stays within the rigorous bounds`` () =
    Assert.True(available, "run tools/generate_golden.py first")

    let failures = ResizeArray<string>()
    for row in results do
        let case = row.["case"]
        let t = row.["T_K"]
        let parts = componentsFor case t

        let total = parts |> Array.sumBy (fun r -> number r "moleFraction")
        let fractions = parts |> Array.map (fun r -> number r "moleFraction" / total)
        let conductivities = parts |> Array.map (fun r -> number r "k_W_mK")
        let input =
            Array.init parts.Length (fun i ->
                fractions.[i], number parts.[i] "molarMass_g_mol",
                number parts.[i] "mu_Pas", conductivities.[i])

        let ours = Mixing.combineConductivity input
        let lower, upper = Mixing.bounds fractions conductivities

        // The generator writes the same bounds; check both agree, then check ours.
        let refLower = number row "k_lowerBound_W_mK"
        let refUpper = number row "k_upperBound_W_mK"
        if abs (lower - refLower) / refLower > 1e-6 || abs (upper - refUpper) / refUpper > 1e-6 then
            failures.Add $"{case} @ {t} K: bounds disagree with the golden file"
        elif ours < lower * (1.0 - 1e-9) || ours > upper * (1.0 + 1e-9) then
            failures.Add $"{case} @ {t} K: k_mix {ours:F4} outside [{lower:F4}, {upper:F4}]"

    Assert.True(failures.Count = 0, String.Join("\n", failures))

/// The two conductivity models must at least agree in magnitude. The observed
/// spread reaches 14 % on H2-rich mixtures, which is genuine model uncertainty;
/// a 25 % gate catches an implementation error without failing on that.
[<Fact>]
let ``Wassiljewa conductivity is close to Mathur-Tondon-Saxena`` () =
    Assert.True(available, "run tools/generate_golden.py first")

    let failures = ResizeArray<string>()
    for row in results do
        let case = row.["case"]
        let t = row.["T_K"]
        let parts = componentsFor case t
        let total = parts |> Array.sumBy (fun r -> number r "moleFraction")
        let input =
            parts
            |> Array.map (fun r ->
                number r "moleFraction" / total,
                number r "molarMass_g_mol",
                number r "mu_Pas",
                number r "k_W_mK")

        let ours = Mixing.combineConductivity input
        let mathur = number row "k_mathur_W_mK"
        let deviation = abs (ours - mathur) / mathur
        if deviation > 0.25 then
            failures.Add $"{case} @ {t} K: {deviation:P1} from Mathur ({ours:F4} vs {mathur:F4})"

    Assert.True(failures.Count = 0, String.Join("\n", failures))

/// End to end, with our own species data: every process mixture in the manual
/// must evaluate and produce physically sane numbers across the WHB envelope.
[<Fact>]
let ``all process gas mixtures evaluate across the WHB envelope`` () =
    let db =
        match SpeciesDatabase.load () with
        | Success (d, _) -> d
        | Failure msgs -> failwith (msgs |> List.map string |> String.concat "; ")

    let cases =
        [ "Claus SRU",       [ "H2S", 0.04; "SO2", 0.02; "N2", 0.60; "H2O", 0.28; "CO2", 0.06 ]
          "SMR syngas",      [ "H2", 0.50; "CO", 0.10; "CO2", 0.08; "CH4", 0.04; "H2O", 0.28 ]
          "Ammonia synloop", [ "H2", 0.55; "N2", 0.20; "NH3", 0.15; "CH4", 0.07; "Ar", 0.03 ]
          "Ethylene TLE",    [ "C2H4", 0.30; "C2H6", 0.18; "H2", 0.14; "CH4", 0.22
                               "C3H8", 0.06; "C2H2", 0.02; "H2O", 0.08 ]
          "FCC flue gas",    [ "N2", 0.72; "CO2", 0.11; "H2O", 0.10; "SO2", 0.005
                               "NO", 0.005; "Ar", 0.06 ]
          "Nitric acid",     [ "NO", 0.09; "NO2", 0.01; "N2", 0.62; "H2O", 0.16; "O2", 0.0
                               "N2O", 0.01; "CO2", 0.11 ]
          "Sulfur vapour",   [ "S2", 0.10; "S6", 0.03; "S8", 0.02; "N2", 0.55
                               "H2O", 0.25; "COS", 0.03; "CS2", 0.02 ]
          "DRI reformer",    [ "CO", 0.35; "H2", 0.40; "CO2", 0.10; "H2O", 0.08; "N2", 0.07 ] ]

    let failures = ResizeArray<string>()
    for (name, composition) in cases do
        let composition = composition |> List.filter (fun (_, y) -> y > 0.0)
        for tC in [ 250.0; 500.0; 800.0; 1100.0; 1400.0 ] do
            let t = (tC + 273.15) * 1.0<K>
            let result =
                Mixing.fromKeys db composition
                >>= fun mix -> Mixing.evaluate mix t 1.5<bar>
            match result with
            | Failure msgs ->
                failures.Add ($"{name} @ {tC} degC: " + (msgs |> List.map string |> String.concat "; "))
            | Success (p, _) ->
                if Double.IsNaN p.Prandtl || p.Prandtl <= 0.05 || p.Prandtl > 2.0 then
                    failures.Add $"{name} @ {tC} degC: Prandtl {p.Prandtl:F3} implausible"
                if float p.Viscosity <= 0.0 || float p.Viscosity > 2e-4 then
                    failures.Add $"{name} @ {tC} degC: viscosity {p.Viscosity} implausible"
                if float p.Density <= 0.0 then
                    failures.Add $"{name} @ {tC} degC: non-positive density"

    Assert.True(failures.Count = 0, String.Join("\n", failures))

/// Mixture properties must vary smoothly with temperature: no jump where a
/// correlation switches interval. A discontinuity here would destabilise any
/// marching solver downstream.
[<Fact>]
let ``mixture properties are continuous across correlation interval joins`` () =
    let db =
        match SpeciesDatabase.load () with
        | Success (d, _) -> d
        | Failure _ -> failwith "database did not load"

    let composition = [ "N2", 0.60; "H2O", 0.28; "CO2", 0.06; "H2S", 0.04; "SO2", 0.02 ]
    let evaluate (tK: float) =
        Mixing.fromKeys db composition
        >>= fun mix -> Mixing.evaluate mix (tK * 1.0<K>) 1.5<bar>

    let failures = ResizeArray<string>()
    // NASA-9 segments join at 1000 K, NASA transport intervals at 1000 K too.
    for join in [ 1000.0; 1073.2 ] do
        match evaluate (join - 0.5), evaluate (join + 0.5) with
        | Success (a, _), Success (b, _) ->
            let jump (x: float) (y: float) = abs (y - x) / abs x
            if jump (float a.SpecificHeat) (float b.SpecificHeat) > 0.01 then
                failures.Add $"cp jumps {jump (float a.SpecificHeat) (float b.SpecificHeat):P2} at {join} K"
            if jump (float a.Viscosity) (float b.Viscosity) > 0.02 then
                failures.Add $"mu jumps at {join} K"
            if jump (float a.ThermalConductivity) (float b.ThermalConductivity) > 0.02 then
                failures.Add $"k jumps at {join} K"
        | _ -> failures.Add $"evaluation failed near {join} K"

    Assert.True(failures.Count = 0, String.Join("\n", failures))
